const input = $input.first().json;
const allowedFamilies = new Set(input.allowed_family_ids || []);
const allowedNeeds = new Set(input.allowed_training_need_ids || []);
const plans = [];
let remaining = input.budget_remaining || 0;
for (const row of input.baseline_rows || []) {
  const eligible = input.llm_enabled && ['ambiguous','unclassified'].includes(row.classification_status) && row.description_excerpt && remaining > 0;
  if (!eligible) { plans.push({ offer_key: row.offer_key, status: input.llm_enabled ? 'skipped_not_eligible_or_budget' : 'skipped_disabled', fallback: true, api_call_count: 0 }); continue; }
  remaining -= 1;
  const out = input.provider_outputs_by_offer_key[row.offer_key];
  let status = 'accepted_optional'; let reason = null;
  if (!out || typeof out !== 'object') { status = 'invalid_output'; reason = 'G8N_LLM_INVALID_JSON'; }
  else if ((out.family_ids || []).some((id) => !allowedFamilies.has(id)) || (out.training_need_ids || []).some((id) => !allowedNeeds.has(id))) { status = 'invalid_output'; reason = 'G8N_LLM_UNKNOWN_TAXONOMY_ID'; }
  plans.push({ offer_key: row.offer_key, status, reason, fallback: status !== 'accepted_optional', api_call_count: 1, cache_write: status === 'accepted_optional', output_json: status === 'accepted_optional' ? JSON.stringify(out) : null });
}
return [{ json: { ...input, optional_llm_plans: plans, remaining_budget: remaining } }];
